const zSyn = (o, arr) => { o._syn = arr; return o };
const zRepr = L => "[" + L.map(t => "{" + Object.entries(t).map(([k, v]) => `'${k}': ${typeof v == "string" ? `'${v}'` : v}`).join(", ") + "}").join(", ") + "]";
const zValid = L => { const seen = new Set(); let bad = 0; for (const t of L) { const dup = seen.has(t.id); seen.add(t.id); if (dup || !["deposit", "withdraw"].includes(t.type) || t.amount < 0) bad++ } return bad };
const zTxs = (n, faults) => { const L = Array.from({ length: n }, (_, i) => ({ id: i + 1, type: aPick(["deposit", "withdraw"]), amount: fR(2, 9) * 10 })); const pos = pShuf(Array.from({ length: n - 1 }, (_, i) => i + 1)); faults.forEach((f, i) => { const p = pos[i]; if (f == "dup") L[p].id = L[p - 1].id; else if (f == "type") L[p].type = aPick(["gift", "refund"]); else L[p].amount = -L[p].amount }); return L };
const zPyValid = "def bad(L):\n    seen = set(); n = 0\n    for t in L:\n        dup = t['id'] in seen\n        seen.add(t['id'])\n        if dup or t['type'] not in ('deposit', 'withdraw') or t['amount'] < 0:\n            n += 1\n    return n\n";

