/* ===== rl1: rate limiter ===== */
const zRl = (times, L, W) => { const q = [], acc = []; for (const t of times) { while (q.length && q[0] <= t - W) q.shift(); if (q.length < L) { q.push(t); acc.push(1) } else acc.push(0) } return acc };
const zRlPy = "def sim(times, L, W):\n    q = []; out = []\n    for t in times:\n        while q and q[0] <= t - W:\n            q.pop(0)\n        if len(q) < L:\n            q.append(t); out.append(1)\n        else:\n            out.append(0)\n    return out\n";
const zTimes = n => { let t = 0; return Array.from({ length: n }, () => (t += fR(0, 2))) };
const zRule = (L, W) => `Giới hạn: tối đa ${L} yêu cầu trong mỗi ${W} giây. Với yêu cầu đến lúc t, chỉ các thời điểm đã chấp nhận LỚN HƠN t - ${W} còn được tính. Yêu cầu bị từ chối không được ghi lại.`;
