/* ===== ap3: stack Undo và ngoặc ===== */
const zBr = s => { const st = []; const m = { ")": "(", "]": "[" }; for (const ch of s) { if ("([".includes(ch)) st.push(ch); else { if (!st.length) return "R2"; if (st.pop() != m[ch]) return "R3" } } return st.length ? "R1" : "OK" };
const zBrPy = "def chk(s):\n    st = []\n    m = {')': '(', ']': '['}\n    for ch in s:\n        if ch in '([':\n            st.append(ch)\n        else:\n            if not st:\n                return 'R2'\n            if st.pop() != m[ch]:\n                return 'R3'\n    return 'R1' if st else 'OK'\n";
const zBrR = { R1: "còn ngoặc mở chưa được đóng", R2: "gặp ngoặc đóng khi chưa có ngoặc mở nào", R3: "ngoặc đóng không khớp với ngoặc mở gần nhất" };
const zBrGen = () => { const pool = ["(", ")", "[", "]"]; let s; do { s = Array.from({ length: fR(3, 6) }, () => aPick(pool)).join("") } while (false); return s };
