  flip: () => { const u = fR(1, 3), r = fR(1, 4); return fT(`Sau khi bấm Undo ${u} lần, lịch sử còn ${r} thao tác. Ban đầu người dùng đã thực hiện bao nhiêu thao tác?`, u + r, `${r} + ${u} = ${u + r}.`) },
  new: () => { let s; do { s = zBrGen() } while (zBr(s) == "OK" && Math.random() < 0.5); const r = zBr(s), c = zBrPy + `print(chk('${s}'))`; return aPy(fC(`Kiểm tra chuỗi ngoặc "${s}" bằng stack (mở thì cất vào, đóng thì lấy ra so khớp). Kết luận?`, r == "OK" ? ["Hợp lệ", "Không hợp lệ", "Không đủ thông tin"] : [`Không hợp lệ: ${zBrR[r]}`, "Hợp lệ", `Không hợp lệ: ${zBrR[r == "R1" ? "R2" : "R1"]}`], r == "OK" ? "Mọi ngoặc đóng đều khớp ngoặc mở gần nhất và stack rỗng ở cuối." : `Dừng theo stack: ${zBrR[r]}.`), c, [r]) },
  verdict: KV("Hà nói: 'Undo hoàn tác thao tác đầu tiên mà người dùng đã làm'. Hà nói đúng hay sai?", "Hà nói: 'Undo hoàn tác thao tác gần nhất, vì stack vào sau ra trước'. Hà nói đúng hay sai?", "Ngoặc/thao tác mới nhất phải được xử lý trước", "Thao tác cũ nhất ra trước", "Thứ tự ngẫu nhiên", "Sai: Undo hoàn tác thao tác gần nhất."),
  read: () => { const S = ["(()", "())", ")(", "[(])", "(]"], s = aPick(S), r = zBr(s), c = zBrPy + `print(chk('${s}'))`, eq = s.split("(").length - 1 == s.split(")").length - 1 && !s.includes("["); return aPy(fC(`Chuỗi "${s}". ${eq ? "Số ngoặc mở bằng số ngoặc đóng. " : ""}Có hợp lệ không?`, [`Không hợp lệ: ${zBrR[r]}`, "Hợp lệ, vì ngoặc đủ cặp", `Không hợp lệ: ${zBrR[r == "R1" ? "R2" : "R1"]}`], `Đếm đủ cặp chưa đủ: thứ tự mới quan trọng. Stack báo: ${zBrR[r]}.`), c, [r]) }
