function zFs(sizeRoot) { const leaf = () => ({ size: fR(1, 9), children: [] }); const dir = () => ({ size: 0, children: [leaf(), leaf()].slice(0, fR(1, 2)) }); const root = { size: sizeRoot, children: [leaf(), dir()] }; if (Math.random() < 0.5) root.children.push(leaf()); return root }
const zFsLit = n => `{"size": ${n.size}, "children": [${n.children.map(zFsLit).join(", ")}]}`;
const zFsTot = n => n.size + n.children.reduce((s, c) => s + zFsTot(c), 0);
const zFsCnt = n => 1 + n.children.reduce((s, c) => s + zFsCnt(c), 0);
const zFsDepth = n => 1 + Math.max(0, ...n.children.map(zFsDepth));
const zFsFn = "def total(n):\n    s = n[\"size\"]\n    for c in n[\"children\"]:\n        s += total(c)\n    return s\n";
PRB.ap5 = {
  same: () => { const t = zFs(0), c = `tree = ${zFsLit(t)}\n` + zFsFn + "print(total(tree))"; return aPy(fT(`${fPre(c.replace("\nprint(total(tree))", ""))}Mỗi nút là tệp (size là dung lượng) hoặc thư mục (size 0, children là các nút con). In ra total(tree) là mấy?`, zFsTot(t), `Cộng dung lượng mọi nút từ lá lên: ${zFsTot(t)}.`), c, [String(zFsTot(t))]) },
  flip: () => { const a = fR(2, 9), b = fR(2, 9), x = fR(2, 9); return fT(`Thư mục gốc (size 0) chứa ba tệp: ${a}, ${b} và một tệp chưa biết. total(gốc) = ${a + b + x}. Tệp chưa biết có dung lượng bao nhiêu?`, x, `${a + b + x} - ${a} - ${b} = ${x}.`) },
  new: () => { const t = zFs(0), n = zFsCnt(t), c = `tree = ${zFsLit(t)}\ndef dem(n):\n    k = 1\n    for c in n["children"]:\n        k += dem(c)\n    return k\nprint(dem(tree))`; return aPy(fT(`${fPre(`tree = ${zFsLit(t)}`)}Sơ đồ công ty: mỗi nút là một nhân sự, children là người họ quản lý. Hàm dem đếm mỗi nút một lần (1 + tổng dem của các con). dem(tree) bằng mấy?`, n, `Đếm mọi nút: ${n}.`), c, [String(n)]) },
  verdict: KV("Hà nói: 'thư mục tự có sẵn một con số dung lượng, chỉ cần đọc ra'. Hà nói đúng hay sai?", "Hà nói: 'dung lượng thư mục là tổng dung lượng mọi thứ nằm trong nó, tính bằng đệ quy'. Hà nói đúng hay sai?", "Thư mục chỉ là cái chứa, dung lượng nằm ở các tệp", "Thư mục tự biết dung lượng", "Chỉ cộng tệp cấp ngoài cùng", "Sai: phải cộng từ lá lên."),
  read: () => { const s = fR(2, 4), t = zFs(s), tot = zFsTot(t), kids = tot - s, c = `tree = ${zFsLit(t)}\n` + zFsFn + "print(total(tree))"; return aPy(aNum(`${fPre(`tree = ${zFsLit(t)}`)}Hàm total cộng size của chính nút rồi cộng total của các con. Chú ý: nút GỐC này có size ${s}, không phải 0. total(tree) bằng mấy?`, tot, `Phải cộng cả size của gốc (${s}) với phần các con (${kids}): ${tot}.`, [kids, s]), c, [String(tot)]) }
};
